    ["Barre d'infos"] = "Barra de información",
    ["Barre d'infos à côté de l'icône"] = "Barra de información junto al icono",
    ["Barre de coups blancs"] = "Barra de golpes automáticos",
    ["Barre de coups blancs : le minuteur de ton attaque automatique, pour placer tes coups au bon moment."] = "Barra de golpes automáticos: el temporizador de tu ataque automático, para colocar tus golpes en el momento justo.",
    ["Barre de coups blancs, rappel de buffs, fenêtre de menace, mana de ton healer et contrôles des mobs."] = "Barra de golpes automáticos, recordatorio de beneficios, ventana de amenaza, maná de tu sanador y controles de los monstruos.",
    ["Barres d'action"] = "Barras de acción",
    ["Barres d'incantation : une couleur à part quand ton interruption est prête."] = "Barras de lanzamiento: un color aparte cuando tu interrupción está lista.",
    ["Barres d'incantation Platyplus"] = "Barras de lanzamiento de Platyplus",
    ["Besoin"] = "Necesidad",
    ["Besoin pour sa 2e spécialisation"] = "Necesidad para su 2.ª especialización",
    ["Bientôt : boss, butin et quêtes pas encore connus."] = "Próximamente: jefes, botín y misiones aún no conocidos.",
    ["Bienvenue"] = "Bienvenido",
    ["Bienvenue dans %s"] = "Te damos la bienvenida a %s",
    ["Bijou"] = "Abalorio",
    ["Bilan"] = "Balance",
    ["Blizzard exige un clic ou une touche pour chaque mise en vente : aucun addon ne peut tout poster seul. Choisis une touche dans /pp > Vente > Hôtel des ventes, ou crée une macro « /click %s »."] = "Blizzard exige un clic o una tecla por cada puesta a la venta: ningún addon puede publicarlo todo solo. Elige una tecla en /pp > Venta > Casa de subastas, o crea una macro «/click %s».",
    ["Boisson choisie hors combat, puis la potion de mana prise en combat. Mis à jour quand tes sacs changent."] = "Bebida elegida fuera de combate y, después, la poción de maná usada en combate. Se actualiza cuando cambian tus bolsas.",
    ["Bon à savoir"] = "Conviene saber",
    ["Bonus de repos"] = "Bonificación de descanso",
    ["Bord de couleur sur ta cible"] = "Borde de color en tu objetivo",
    ["Boss précédent"] = "Jefe anterior",
    ["Boss suivant"] = "Jefe siguiente",
    ["Bouton « copier le chat »"] = "Botón «copiar el chat»",
    ["Buffs de tes alliés : %s - %s"] = "Beneficios de tus aliados: %s - %s",
    ["Buffs que mes alliés peuvent me donner"] = "Beneficios que mis aliados pueden darme",
    ["Buffs que mon groupe peut me donner"] = "Beneficios que mi grupo puede darme",
    ["Buffs à demander"] = "Beneficios que pedir",
    ["Buffs à demander — glisse-moi"] = "Beneficios que pedir — arrástrame",
    ["Butin"] = "Botín",
    ["Bénéfice"] = "Beneficio",
    ["C'est parti"] = "¡Vamos allá!",
    ["C, U et les autres touches du jeu ouvrent le bon onglet ; la même touche ou Échap la referme."] = "C, U y las demás teclas del juego abren la pestaña correcta; la misma tecla o Esc la cierra.",
    ["CONSEILLÉ"] = "RECOMENDADO",
    ["CVars utiles (SoftTarget*, autoLoot*)"] = "CVars útiles (SoftTarget*, autoLoot*)",
    ["Cache la fenêtre de dialogue animée (« tête parlante ») qui apparaît en haut de l'écran."] = "Oculta la ventana de diálogo animada («cabeza parlante») que aparece en la parte superior de la pantalla.",
    ["Cache les barres d'expérience et de réputation de Blizzard. L'XP reste lisible dans la barre d'infos de Platyplus (pourcentage, XP par heure, temps avant le niveau). Coupé, les barres reviennent tout de suite."] = "Oculta las barras de experiencia y de reputación de Blizzard. La XP sigue visible en la barra de información de Platyplus (porcentaje, XP por hora, tiempo hasta el nivel). Si lo desactivas, las barras vuelven al instante.",
    ["Cache les cartes pour cette quête ; la fenêtre de Blizzard reste ouverte."] = "Oculta las tarjetas para esta misión; la ventana de Blizzard sigue abierta.",
    ["Cache les messages d'erreur rouges qui s'affichent au milieu de l'écran."] = "Oculta los mensajes de error rojos que aparecen en medio de la pantalla.",
    ["Cache les mobs que tu tiens déjà ; la fenêtre ne montre que ce qui demande ton attention."] = "Oculta los monstruos que ya tienes bajo control; la ventana solo muestra lo que requiere tu atención.",
    ["Cacher les icônes de Questie"] = "Ocultar los iconos de Questie",
    ["Cachée, tu ouvres toujours les options avec /pp."] = "Aunque esté oculta, siempre puedes abrir las opciones con /pp.",
    ["Cadavres avec du butin"] = "Cadáveres con botín",
    ["Cadre"] = "Marco",
    ["Cadre Platyplus"] = "Marco de Platyplus",
    ["Canal"] = "Canal",
    ["Canal %d"] = "Canal %d",
    ["Canaux"] = "Canales",
    ["Caractéristiques"] = "Características",
    ["Carré"] = "Cuadrado",
    ["Carte"] = "Mapa",
    ["Cases par ligne"] = "Casillas por fila",
    ["Ce joueur avait déjà lancé les dés : ce jet ne compte pas."] = "Este jugador ya había tirado los dados: esta tirada no cuenta.",
    ["Ce qu'il faut faire s'affiche en grand près de ton personnage, avec la touche à presser."] = "Lo que hay que hacer se muestra en grande junto a tu personaje, con la tecla que pulsar.",
    ["Ce qu'un mob peut te faire subir, avant de le taper."] = "Lo que un monstruo puede hacerte, antes de golpearlo.",
    ["Ce que fait la touche"] = "Qué hace la tecla",
    ["Ce que le jeu fait réellement quand tu appuies sur ta touche, en ce moment. Hors dialogue c'est l'interaction rapide ; pendant un dialogue de PNJ c'est l'avance du dialogue."] = "Lo que hace realmente el juego ahora cuando pulsas tu tecla. Fuera de un diálogo es la interacción rápida; durante un diálogo con un PNJ es el avance del diálogo.",
    ["Ce que te disent les PNJ dans une fenêtre Platyplus : discussion, quête proposée, objets à rapporter, récompenses. Texte en grand, déplaçable."] = "Lo que te dicen los PNJ en una ventana de Platyplus: conversación, misión propuesta, objetos que traer, recompensas. Texto grande y movible.",
    ["Ce que tu gagnes défile à côté de ton personnage : butin, achats, objets fabriqués, récompenses de quête."] = "Lo que ganas se desplaza junto a tu personaje: botín, compras, objetos fabricados, recompensas de misión.",
    ["Ce que tu ouvres avec C : équipement, caractéristiques, réputation, compétences, JcJ, dans une fenêtre Platyplus à onglets."] = "Lo que abres con C: equipo, características, reputación, habilidades, JcJ, en una ventana de Platyplus con pestañas.",
    ["Ce que tu ramasses, fabriques, achètes ou vends s'affiche près de ton personnage, les objets identiques se cumulent, puis tout s'estompe."] = "Lo que recoges, fabricas, compras o vendes aparece junto a tu personaje, los objetos iguales se acumulan y luego todo se desvanece.",
    ["Ce qui serait vendu chez un marchand avec les réglages actuels. Mis à jour à l'ouverture de l'onglet et à chaque changement de réglage."] = "Lo que se vendería a un vendedor con los ajustes actuales. Se actualiza al abrir la pestaña y con cada cambio de ajuste.",
    ["Ce réglage n'existe pas sur ton client."] = "Este ajuste no existe en tu cliente.",
    ["Ces objets sont toujours épargnés, quelle que soit leur qualité."] = "Estos objetos nunca se venden, sea cual sea su calidad.",
    ["Ces objets sont vendus à chaque marchand, même s'ils ne sont pas gris."] = "Estos objetos se venden en cada vendedor, aunque no sean grises.",
    ["Ceux qui ne marchent qu'après un événement : Fulgurance après une esquive, Exécution sous 20 % de vie."] = "Los que solo funcionan tras un suceso: Abrumar tras una esquiva, Ejecutar por debajo del 20 % de vida.",
    ["Changer la touche"] = "Cambiar la tecla",
    ["Chaque donjon : ses boss et leur butin, ses quêtes (où les prendre, les suites de quêtes, les récompenses), son plan et le chemin jusqu'à l'entrée. Ouvrir : /dj, /pp donjons, le menu de l'icône Platyplus, ou la touche de l'addon DungeonJournal."] = "Cada mazmorra: sus jefes y su botín, sus misiones (dónde cogerlas, las cadenas de misiones, las recompensas), su mapa y el camino hasta la entrada. Abrir: /dj, /pp donjons, el menú del icono de Platyplus o la tecla del addon DungeonJournal.",
    ["Chaque donjon : ses boss et leur butin, ses quêtes (où les prendre, les suites de quêtes, les récompenses), son plan et le chemin jusqu'à l'entrée. Touche : Raccourcis > Journal des donjons. Aussi : /dj, /pp donjons, ou le menu de l'icône Platyplus."] = "Cada mazmorra: sus jefes y su botín, sus misiones (dónde conseguirlas, cadenas de misiones, recompensas), su mapa y el camino hasta la entrada. Tecla: Atajos > Diario de mazmorras. También: /dj, /pp donjons, o el menú del icono de Platyplus.",
    ["Chaque objet gagné s'affiche quelques secondes à côté de ton personnage, avec sa quantité."] = "Cada objeto ganado se muestra unos segundos junto a tu personaje, con su cantidad.",
    ["Chaque objet vendu apparaît dans le flux avec son prix, puis le total encaissé."] = "Cada objeto vendido aparece en el flujo con su precio y, después, el total cobrado.",
    ["Chargement…"] = "Cargando…",
    ["Charges arcaniques"] = "Cargas arcanas",
    ["Chat"] = "Chat",
    ["Chemise"] = "Camisa",
    ["Chercher"] = "Buscar",
    ["Chercher les prix dès l'ouverture"] = "Buscar los precios nada más abrir",
    ["Chercher…"] = "Buscar…",
    ["Chez un marchand, tous tes objets gris sont vendus."] = "En un vendedor, se venden todos tus objetos grises.",
    ["Chi"] = "Chi",
    ["Chiffres sur les barres de vie et de ressource"] = "Números en las barras de vida y de recurso",
    ["Chiffres sur les temps de recharge"] = "Números en los tiempos de reutilización",
    ["Choisir aussi la 1re option de dialogue"] = "Elegir también la 1.ª opción de diálogo",
    ["Choisis les infos affichées dans l'onglet Icône & infos."] = "Elige la información mostrada en la pestaña Icono e información.",
    ["Choisis ta base"] = "Elige tu base",
    ["Choisis ta récompense"] = "Elige tu recompensa",
    ["Choisis un objet (clic ou touche 1, 2, 3...), puis rends la quête :"] = "Elige un objeto (clic o tecla 1, 2, 3...) y entrega la misión:",
    ["Choisis une carte"] = "Elige una tarjeta",
    ["Choisis une récompense"] = "Elige una recompensa",
    ["Chuchote"] = "Susurra",
    ["Cible ton healer, puis clique : la barre suit ce joueur tant qu'il est dans ton groupe, même si le groupe ne lui a pas donné le rôle de soigneur (aussi : /pp healer cible)."] = "Selecciona a tu sanador y pulsa: la barra sigue a ese jugador mientras esté en tu grupo, aunque el grupo no le haya dado el rol de sanador (también: /pp healer cible).",
    ["Cibler l'ennemi qui est devant moi"] = "Fijar como objetivo al enemigo que tengo delante",
    ["Clic"] = "Clic",
    ["Clic : choisir · double-clic : choisir et rendre la quête"] = "Clic: elegir · doble clic: elegir y entregar la misión",
    ["Clic : cocher pour le mettre en vente (retenu pour les prochaines fois)"] = "Clic: marcar para ponerlo a la venta (se recuerda para la próxima vez)",
    ["Clic : copier ce message"] = "Clic: copiar este mensaje",
    ["Clic : décocher (il ne sera plus mis en vente)"] = "Clic: desmarcar (ya no se pondrá a la venta)",
    ["Clic : ouvrir la fiche du personnage"] = "Clic: abrir la hoja del personaje",
    ["Clic droit : ne plus jamais le proposer"] = "Clic derecho: no volver a proponerlo nunca",
    ["Clic droit : poser ou retirer le marqueur Crâne"] = "Clic derecho: poner o quitar la marca de Calavera",
    ["Clic droit pour valider - les lignes descendent"] = "Clic derecho para confirmar - las líneas bajan",
    ["Clic droit pour valider - les lignes montent"] = "Clic derecho para confirmar - las líneas suben",
    ["Clic droit sur le libellé : valeur par défaut."] = "Clic derecho en la etiqueta: valor por defecto.",
    ["Clic droit sur un paladin, un prêtre, un mage… : « Demander un buff » lui chuchote ta demande."] = "Clic derecho en un paladín, un sacerdote, un mago…: «Pedir un beneficio» le susurra tu petición.",
    ["Clic gauche : les options. Clic droit : un menu pour allumer ou couper les fonctions. Glisse-la pour la déplacer."] = "Clic izquierdo: las opciones. Clic derecho: un menú para activar o desactivar funciones. Arrástrala para moverla.",
    ["Clic sur la grande pastille : choisir une couleur. Clic droit : défaut."] = "Clic en la muestra grande: elegir un color. Clic derecho: valor por defecto.",
    ["Clignote quand un mob t'échappe"] = "Parpadea cuando un monstruo se te escapa",
    ["Clignoter quand un mob m'échappe"] = "Parpadear cuando un monstruo se me escapa",
    ["Clique encore pour confirmer"] = "Haz clic de nuevo para confirmar",
    ["Clique encore pour recharger"] = "Haz clic de nuevo para recargar",
    ["Clique encore pour remplacer tes réglages actuels par ce mode."] = "Haz clic otra vez para reemplazar tus ajustes actuales por este modo.",
    ["Clique encore pour vider"] = "Haz clic de nuevo para vaciar",
    ["Clique ici : cibler %s"] = "Haz clic aquí: seleccionar a %s",
    ["Clique ici : cibler ce mob"] = "Haz clic aquí: seleccionar a este enemigo",
    ["Clique ici pour changer de touche"] = "Haz clic aquí para cambiar de tecla",
    ["Clique ici puis appuie sur la touche voulue (avec Maj, Ctrl ou Alt si tu veux). Pour un bouton de souris (molette, boutons latéraux), clique dans ce cadre avec ce bouton. Échap annule."] = "Haz clic aquí y pulsa la tecla que quieras (con Mayús, Ctrl o Alt si lo deseas). Para un botón del ratón (rueda, botones laterales), haz clic en este marco con ese botón. Esc cancela.",
    ["Clique sur « %s » pour avoir Platyplus dans la langue de ton jeu."] = "Haz clic en «%s» para tener Platyplus en el idioma de tu juego.",
    ["Clique sur « Actualiser l'aperçu » pour voir ce qui serait vendu."] = "Pulsa «Actualizar la vista previa» para ver lo que se vendería.",
    ["Coche les objets à vendre"] = "Marca los objetos que quieres vender",
    ["Coche les objets à vendre (clic sur la ligne) : tes choix sont retenus pour la prochaine fois."] = "Marca los objetos que quieres vender (clic en la línea): tus elecciones se recuerdan para la próxima vez.",
    ["Coché : le nom en couleur puis le texte, sans bulle ; les messages qui se suivent du même joueur (moins d'une minute) se resserrent, sans répéter l'heure. Clic sur l'heure ou clic droit sur le message : copier. Coupé : une ligne brute par message (« 15:27 [Guilde] Bob : salut »)."] = "Activado: el nombre en color y luego el texto, sin globo; los mensajes seguidos del mismo jugador (menos de un minuto) se juntan, sin repetir la hora. Clic en la hora o clic derecho en el mensaje: copiar. Desactivado: una línea simple por mensaje («15:27 [Hermandad] Bob: hola»).",
    ["Combat"] = "Combate",
    ["Combien de lignes le flux peut afficher en même temps. Les plus anciennes disparaissent en premier."] = "Cuántas líneas puede mostrar el flujo a la vez. Las más antiguas desaparecen primero.",
    ["Commandes"] = "Comandos",
    ["Comme Threat Plates : qui tape qui, d'un coup d'œil, et un look à ton goût."] = "Como Threat Plates: quién golpea a quién, de un vistazo, y un aspecto a tu gusto.",
    ["Comme le chat du jeu : vert pour la guilde, bleu pour le groupe..."] = "Como el chat del juego: verde para la hermandad, azul para el grupo...",
    ["Comme le jeu"] = "Como el juego",
    ["Comme ton équipement"] = "Como tu equipo",
    ["Commencer la visite"] = "Empezar la visita",
    ["Commun"] = "Común",
    ["Complet"] = "Completo",
    ["Composants"] = "Componentes",
    ["Compétences"] = "Habilidades",
    ["Compétences indisponibles sur ce client."] = "Habilidades no disponibles en este cliente.",
    ["Confirmer : %s"] = "Confirmar: %s",
    ["Confirmer seul les objets « lié quand ramassé »"] = "Confirmar solo los objetos «ligado al recogerlo»",
    ["Confort"] = "Comodidad",
    ["Contrôle l'esprit"] = "Control mental",
    ["Contrôles des mobs"] = "Controles de los monstruos",
    ["Coordonnées"] = "Coordenadas",
    ["Copie"] = "Copia",
    ["Copier le chat"] = "Copiar el chat",
    ["Copier le message"] = "Copiar el mensaje",
    ["Couleur de la progression"] = "Color del progreso",
    ["Couleur du bord"] = "Color del borde",
    ["Couleur du clignotement"] = "Color del parpadeo",
    ["Couleur du fond"] = "Color del fondo",
    ["Couleur selon qu'on peut l'interrompre, et le temps restant."] = "Color según se pueda interrumpir o no, y el tiempo restante.",
    ["Couleur « autre tank »"] = "Color «otro tanque»",
    ["Couleur « interruption prête »"] = "Color «interrupción lista»",
    ["Couleurs"] = "Colores",
    ["Couleurs de menace"] = "Colores de amenaza",
    ["Coup blanc"] = "Ataque normal",
    ["Coupe l'option « icônes d'objectif sur les plates » de Questie. Décoche pour la rallumer."] = "Desactiva la opción «iconos de objetivo en las placas de nombre» de Questie. Desmárcalo para reactivarla.",
    ["Coupé : le cadre du jeu (large, avec une ombre en bas à droite) revient, coins carrés."] = "Desactivado: vuelve el marco del juego (ancho, con una sombra abajo a la derecha), esquinas cuadradas.",
    ["Coupé : le texte des messages est en clair, seul le [canal] prend sa couleur. Coché : le texte aussi, comme dans le chat du jeu."] = "Desactivado: el texto de los mensajes va en claro, solo el [canal] toma su color. Activado: el texto también, como en el chat del juego.",
    ["Coupé, il ne reste que l'icône (et le nom si tu le gardes) : tu connais déjà ta touche."] = "Si lo desactivas, solo queda el icono (y el nombre si lo conservas): ya conoces tu tecla.",
    ["Coupés : les alertes de combat, la barre de coups blancs, le butin affiché à l'écran, la fenêtre de menace, la barre d'infos, les plates colorées, les contrôles des mobs dans l'infobulle, le niveau d'objet et les messages d'erreur rouges. Restent : la touche (tu choisis toi-même tes réponses aux PNJ), le loot instantané, la vente, les grandes fenêtres de quête avec leur histoire dépliée, la caméra plus loin."] = "Desactivados: las alertas de combate, la barra de golpes automáticos, el botín mostrado en pantalla, la ventana de amenaza, la barra de información, las placas de colores, los controles de los enemigos en la descripción, el nivel de objeto y los mensajes de error rojos. Se mantienen: la tecla (eliges tú mismo tus respuestas a los PNJ), el botín instantáneo, la venta, las ventanas de misión grandes con su historia desplegada, la cámara más lejos.",
    ["Coût : %s"] = "Coste: %s",
    ["Coût et bénéfice des recettes"] = "Coste y beneficio de las recetas",
    ["Cri de guerre"] = "Grito de batalla",
    ["Cri de guerre en combat"] = "Grito de batalla en combate",
    ["Cri de guerre manquant"] = "Falta el grito de batalla",
    ["Ctrl"] = "Ctrl",
    ["Ctrl+C : traduire   ·   Échap : fermer"] = "Ctrl+C: traducir   —   Esc: cerrar",
    ["Ctrl+C pour copier · Échap pour fermer"] = "Ctrl+C para copiar · Esc para cerrar",
    ["Cupidité"] = "Codicia",
    ["D'autres onglets t'attendent : Confort (invitations, duels, invocations), Réglages du jeu (réglages conseillés en un clic) et Avancé (langue de Platyplus, remise à zéro)."] = "Te esperan otras pestañas: Comodidad (invitaciones, duelos, invocaciones), Ajustes del juego (ajustes recomendados con un clic) y Avanzado (idioma de Platyplus, restablecer).",
    ["DURABILITÉ"] = "DURABILIDAD",
    ["Danger"] = "Peligro",
    ["Dans l'infobulle des mobs"] = "En la descripción emergente de los monstruos",
    ["Dans la zone de saisie, les flèches haut et bas remontent les messages et commandes que tu as déjà envoyés (les 32 derniers), même après un /reload. Coupé : il faut Alt + flèches, comme dans le jeu de base."] = "En el cuadro de texto, las flechas arriba y abajo recuperan los mensajes y comandos que ya enviaste (los 32 últimos), incluso tras un /reload. Desactivado: hay que usar Alt + flechas, como en el juego base.",
    ["Dans le même onglet, deux touches de plus pour manger et boire le meilleur de tes sacs (une potion en combat)."] = "En la misma pestaña, dos teclas más para comer y beber lo mejor de tus bolsas (una poción en combate).",
    ["Dans les options, survole un réglage pour lire son explication. Clic droit sur un curseur : il revient à sa valeur par défaut."] = "En las opciones, pasa el ratón por un ajuste para leer su explicación. Clic derecho en un control deslizante: vuelve a su valor por defecto.",
    ["Dans tous les canaux."] = "En todos los canales.",
    ["Dans un dialogue, la même touche fait défiler le texte, accepte la quête, puis la rend."] = "En un diálogo, la misma tecla avanza el texto, acepta la misión y luego la entrega.",
    ["De coins carrés (0) à des bouts bien ronds (4)."] = "De esquinas cuadradas (0) a puntas bien redondas (4).",
    ["De l'eau"] = "Agua",
    ["De la nourriture"] = "Comida",
    ["De petits éclats dorés sur la plante la plus proche."] = "Pequeños destellos dorados en la planta más cercana.",
    ["Demande les prix dès que tu ouvres l'HDV : une seule recherche groupée pour tes marchandises (minerais, herbes, tissus...), puis une par pièce d'équipement. Tu peux mettre en vente pendant que la recherche continue. Coupé : clique « Rechercher à nouveau » dans le panneau."] = "Pide los precios en cuanto abres la casa de subastas: una sola búsqueda conjunta para tus mercancías (minerales, hierbas, telas...) y luego una por pieza de equipo. Puedes poner a la venta mientras la búsqueda continúa. Desactivado: pulsa «Buscar de nuevo» en el panel.",
    ["Demander un buff"] = "Pedir un beneficio",
    ["Demander un buff au clic droit"] = "Pedir un beneficio con clic derecho",
    ["Des alertes de combat lisibles"] = "Alertas de combate legibles",
    ["Des fenêtres plus claires"] = "Ventanas más claras",
    ["Des infos utiles à côté de l'icône, mises à jour sans rien coûter en jeu."] = "Información útil junto al icono, actualizada sin coste de rendimiento en el juego.",
    ["Deux touches qui prennent le meilleur de tes sacs : à manger ou à boire hors combat, une potion en combat."] = "Dos teclas que usan lo mejor de tus bolsas: comida o bebida fuera de combate, una poción en combate.",
    ["Diagnostic"] = "Diagnóstico",
    ["Diagnostic, commandes et réinitialisation."] = "Diagnóstico, comandos y restablecimiento.",
    ["Distance maximale, en mètres, de la cible d'interaction automatique (réglage du jeu « SoftTargetInteractRange »). Une valeur trop grande peut te faire cibler des objets lointains. Expérimental."] = "Distancia máxima, en metros, del objetivo de interacción automática (ajuste del juego «SoftTargetInteractRange»). Un valor demasiado alto puede hacer que fijes objetos lejanos. Experimental.",
    ["Dit dans le chat si le journal du chat est allumé."] = "Lo indica en el chat si el registro del chat está activado.",
    ["Domicile"] = "Local",
    ["Domicile : discussion, hôtel des ventes. Monde : combat et autres joueurs. Vert jusqu'à 100 ms, orange jusqu'à 250 ms, rouge au-delà."] = "Local: chat, casa de subastas. Mundo: combate y otros jugadores. Verde hasta 100 ms, naranja hasta 250 ms, rojo por encima.",
    ["Donjons"] = "Mazmorras",
    ["Double-clic"] = "Doble clic",
    ["Douleur"] = "Dolor",
    ["Doux"] = "Suave",
    ["DungeonJournal %s, par Exehn : le journal, ses données (boss, butin, quêtes, plans, routes) et ses images. Platyplus l'intègre tel quel (dev/make_dungeonjournal.py) et y ajoute la liste de gauche, « À ton niveau » et son style. Tes réglages, favoris et progression du journal sont gardés par Platyplus."] = "DungeonJournal %s, de Exehn: el diario, sus datos (jefes, botín, misiones, mapas, rutas) y sus imágenes. Platyplus lo integra tal cual (dev/make_dungeonjournal.py) y le añade la lista de la izquierda, «A tu nivel» y su estilo. Platyplus guarda tus ajustes, favoritos y progreso del diario.",
    ["DungeonJournal, par Exehn : le journal, ses données (boss, butin, quêtes, plans, routes) et ses images viennent de son addon, installé à part ; Platyplus n'en embarque rien. Platyplus y ajoute la liste de gauche, « À ton niveau » et son style en passant derrière lui, sans rien modifier dans l'addon : éteins les trois réglages (puis /reload) et il retrouve son look d'origine."] = "DungeonJournal, de Exehn: el diario, sus datos (jefes, botín, misiones, mapas, rutas) y sus imágenes vienen de su addon, instalado por separado; Platyplus no incluye nada de él. Platyplus añade la lista de la izquierda, «A tu nivel» y su estilo pasando detrás de él, sin modificar nada en el addon: apaga los tres ajustes (y luego /reload) y recupera su aspecto original.",
    ["Dura"] = "Dur.",
    ["Durabilité"] = "Durabilidad",
    ["Durée"] = "Duración",
    ["Durée d'affichage"] = "Duración de la visualización",
    ["Durée des ventes"] = "Duración de las subastas",
    ["Dès qu'un dialogue de quête s'ouvre, Platyplus accepte la quête ou la rend tout seul, sans touche. Si elle propose plusieurs récompenses, il attend que tu en choisisses une. Maintiens Maj en ouvrant le dialogue pour lire tranquillement."] = "En cuanto se abre un diálogo de misión, Platyplus acepta o entrega la misión solo, sin pulsar tecla. Si ofrece varias recompensas, espera a que elijas una. Mantén Mayús al abrir el diálogo para leer con calma.",
    ["Dès qu'un objet est mis aux dés dans ton groupe."] = "En cuanto se pone a tirada un objeto en tu grupo.",
    ["Déclarer la guerre"] = "Declarar la guerra",
    ["Décoche pour déplacer la fenêtre en tirant son bandeau."] = "Desmarca para mover la ventana arrastrando su barra de título.",
    ["Décoché, la fenêtre reste affichée en permanence."] = "Si está desmarcado, la ventana se queda siempre visible.",
    ["Dégradé Platyplus"] = "Degradado Platyplus",
    ["Départage /roll"] = "Desempate /roll",
    ["Déplacer"] = "Mover",
    ["Dépose ici un objet de tes sacs : il ne sera jamais vendu automatiquement."] = "Suelta aquí un objeto de tus bolsas: nunca se venderá automáticamente.",
    ["Dépose ici un objet de tes sacs : il sera vendu à chaque visite chez un marchand."] = "Suelta aquí un objeto de tus bolsas: se venderá en cada visita a un vendedor.",
    ["Dés lancés à la main"] = "Dados tirados a mano",
    ["Désarme"] = "Desarma",
    ["Détail"] = "Detalle",
    ["Déverrouille l'alerte pour la glisser où tu veux ; reclique (ou clic droit dessus) pour la verrouiller."] = "Desbloquea la alerta para arrastrarla adonde quieras; vuelve a pulsar (o clic derecho en ella) para bloquearla.",
    ["Déverrouille la barre pour la glisser où tu veux ; reclique (ou clic droit sur la barre) pour la verrouiller."] = "Desbloquea la barra para arrastrarla adonde quieras; vuelve a pulsar (o clic derecho en la barra) para bloquearla.",
    ["Déverrouille la barre pour la glisser où tu veux ; reclique pour la verrouiller."] = "Desbloquea la barra para arrastrarla adonde quieras; vuelve a pulsar para bloquearla.",
    ["Déverrouille la rangée des buffs à demander pour la glisser où tu veux ; reclique (ou clic droit dessus) pour la verrouiller."] = "Desbloquea la fila de beneficios que pedir para arrastrarla adonde quieras; vuelve a pulsar (o clic derecho en ella) para bloquearla.",
    ["Effacer"] = "Borrar",
    ["Effacer l'historique"] = "Borrar el historial",
    ["Elle apparaît au début du combat et disparaît en fondu 3 s après la fin."] = "Aparece al empezar el combate y se desvanece 3 s después de terminar.",
    ["Emplacement vide"] = "Hueco vacío",
    ["Emplacements libres restants"] = "Huecos libres restantes",
    ["Empêche de déplacer l'icône par erreur. Déverrouillée, glisse-la où tu veux."] = "Evita mover el icono por error. Desbloqueado, arrástralo adonde quieras.",
    ["En combat ; dorée quand Frappe héroïque attend le prochain coup."] = "En combate; dorada cuando Golpe heroico espera al siguiente golpe.",
    ["En combat seulement : si tu n'as pas ton Cri de guerre, son icône apparaît en grand avec la touche à presser (« Cri de guerre manquant »), bleutée tant que tu n'as pas assez de rage. Elle disparaît dès que tu cries. Il faut que le Cri de guerre soit rangé sur tes barres. Fonctionne même si l'alerte de proc est coupée."] = "Solo en combate: si no tienes tu Grito de batalla, su icono aparece en grande con la tecla que pulsar («Falta Grito de batalla»), azulado mientras no tengas ira suficiente. Desaparece en cuanto gritas. El Grito de batalla debe estar en tus barras. Funciona aunque la alerta de proc esté desactivada.",
    ["En combat, la barre de vie de chaque mob (sa « plate ») prend la couleur de la situation."] = "En combate, la barra de vida de cada monstruo (su «placa») toma el color de la situación.",
    ["En combat, la barre de vie de chaque mob prend une couleur selon sa cible :\n|cff33d14dvert|r : il te tape (tank) — ou il t'ignore (DPS/soins) ;\n|cffff9e1aorange|r : ça se joue, quelqu'un est sur le point de prendre ou de perdre l'aggro ;\n|cfff22e26rouge|r : il tape un allié (tank) — ou il te tape (DPS/soins) ;\n|cff409ef9bleu|r : un autre tank du groupe le tient.\nPlus tout le look ci-dessous. Les plates s'affichent avec la touche V."] = "En combate, la barra de vida de cada monstruo toma un color según su objetivo:\n|cff33d14dverde|r: te golpea a ti (tanque) — o te ignora (DPS/sanación);\n|cffff9e1anaranja|r: se está decidiendo, alguien está a punto de ganar o perder el aggro;\n|cfff22e26rojo|r: golpea a un aliado (tanque) — o te golpea a ti (DPS/sanación);\n|cff409ef9azul|r: otro tanque del grupo lo tiene.\nMás todo el aspecto de abajo. Las placas de nombre se muestran con la tecla V.",
    ["En combat, ton Cri de guerre s'il te manque. Hors combat, ce que tes alliés peuvent te donner et que tu n'as pas, et un clic droit pour le leur demander."] = "En combate, tu Grito de batalla si te falta. Fuera de combate, lo que tus aliados pueden darte y no tienes, y un clic derecho para pedírselo.",
    ["En combat. Tank / DPS : les rôles s'inversent tout seuls."] = "En combate. Tanque / DPS: los roles se invierten solos.",
    ["En donjon ou en raid, une fenêtre suit chaque objet mis aux dés : le choix de chaque joueur (Besoin, Cupidité, Passe), son dé, sa classe, qui mène et qui gagne."] = "En mazmorra o banda, una ventana sigue cada objeto puesto a tirada: la elección de cada jugador (Necesidad, Codicia, Pasar), su tirada, su clase, quién va en cabeza y quién gana.",
    ["En groupe avec deux tanks : un mob tenu par l'autre tank n'est pas « danger » (pas ton problème)."] = "En grupo con dos tanques: un monstruo que tiene el otro tanque no es «peligro» (no es tu problema).",
    ["En groupe, elle s'ouvre quand un objet est mis aux dés et montre le choix et le dé de chaque joueur."] = "En grupo, se abre cuando se sortea un objeto y muestra la elección y la tirada de cada jugador.",
    ["En groupe, une fenêtre de menace liste chaque mob du combat et qui il attaque."] = "En grupo, una ventana de amenaza lista cada monstruo del combate y a quién ataca.",
    ["En groupe, une fenêtre suit les jets de dés : qui fait Besoin ou Cupidité, et qui gagne."] = "En grupo, una ventana sigue las tiradas de dados: quién elige Necesidad o Codicia, y quién gana.",
    ["En guerre : tu peux attaquer ses membres."] = "En guerra: puedes atacar a sus miembros.",
    ["En rouge à %d places libres ou moins."] = "En rojo con %d huecos libres o menos.",
    ["Espace"] = "Espacio",
    ["Essence"] = "Esencia",
    ["Et aussi :"] = "Y además:",
    ["Et celle de réputation, en bas de l'écran."] = "Y la de reputación, en la parte inferior de la pantalla.",
    ["Ex. un chaman kobold lance Éclair : la barre est jaune (interruptible), bleue si ta Volée de coups est prête, grise s'il est protégé (bouclier : rien à faire)."] = "Ej.: un chamán kobold lanza Descarga de relámpagos: la barra es amarilla (interrumpible), azul si tu Zurrar está listo, gris si está protegido (escudo: nada que hacer).",
    ["Ex. « 3/8 » et un ! à côté de la barre d'un loup qu'il te reste à tuer."] = "Ej.: «3/8» y un ! junto a la barra de un lobo que te falta por matar.",
    ["Ex. « Coup de pied rapide — Étourdit 2 s   toutes les 5-9 s »."] = "Ej.: «Patada rápida — Aturde 2 s   cada 5-9 s».",
    ["Exemple"] = "Ejemplo",
    ["Exemple : 10 cases par ligne et 80 places en tout font 8 lignes."] = "Ejemplo: 10 casillas por fila y 80 huecos en total dan 8 filas.",
    ["Exemple : 3 = jusqu'à trois icônes côte à côte (Fulgurance, Exécution et Vengeance prêtes ensemble). Avec 1, seule la première est montrée."] = "Ejemplo: 3 = hasta tres iconos uno al lado del otro (Abrumar, Ejecutar y Venganza listos a la vez). Con 1, solo se muestra el primero.",
    ["Exemple : clic droit sur le portrait d'un paladin, « Demander un buff », « Bénédiction des rois » : il reçoit « Salut, rois stp ? Merci :) » (prêtre : « buff endu », mage : « buff int »…). La liste dépend de sa classe — paladin : les bénédictions ; prêtre : Robustesse, Esprit divin, Protection contre l'Ombre ; druide : Marque du fauve, Épines ; mage : Intelligence des arcanes, nourriture, eau ; démoniste : Respiration interminable, pierre de soins, invocation ; chaman : Respiration aquatique, Marche sur l'eau. En haut de la liste, « Tous ses buffs » envoie « Salut, buff stp ? Merci :) ». Marche aussi sur un nom cliqué dans le chat. En instance, si le jeu cache son nom, la demande part dans le chat du groupe."] = "Ejemplo: clic derecho en el retrato de un paladín, «Pedir un beneficio», «Bendición de reyes»: recibe «Salut, rois stp ? Merci :)» (sacerdote: «buff endu», mago: «buff int»…). La lista depende de su clase — paladín: las bendiciones; sacerdote: Entereza, Espíritu divino, Protección contra las Sombras; druida: Marca de lo Salvaje, Espinas; mago: Intelecto Arcano, comida, agua; brujo: Aliento interminable, piedra de salud, invocación; chamán: Respiración acuática, Caminar sobre el agua. Al principio de la lista, «Todos sus beneficios» envía «Salut, buff stp ? Merci :)». También funciona con un nombre pulsado en el chat. En instancia, si el juego oculta su nombre, la petición va al chat de grupo.",
    ["Exemple : ton Pain de seigle et tes Potions de soins s'affichent ensemble sous Consommables, ton Étoffe de lin sous Artisanat, tes Bottes sous Équipement. Sous Poubelle : l'Os brisé gris et tout ce que la vente automatique vendra chez le marchand. Tes places vides sont à la fin, sous Libre. Seul l'affichage change : les objets ne bougent pas dans tes sacs (le bouton Trier range toujours les sacs du jeu). Coupé : tes sacs à la suite, case par case."] = "Ejemplo: tu Pan de centeno y tus Pociones de curación se muestran juntos en Consumibles, tu Tela de lino en Artesanía, tus Botas en Equipo. En Basura: el Hueso roto gris y todo lo que la venta automática venderá al vendedor. Tus huecos vacíos van al final, en Libre. Solo cambia la visualización: los objetos no se mueven en tus bolsas (el botón Ordenar sigue ordenando las bolsas del juego). Desactivado: tus bolsas una tras otra, casilla por casilla.",
    ["Exemple : tu parles au garde, ses options et ses quêtes s'affichent en lignes cliquables ; tu choisis une quête, son texte, ses objectifs et ses récompenses s'affichent en grand avec les boutons Accepter / Refuser. Les récompenses sont des tuiles colorées selon leur rareté : survol pour l'infobulle, clic pour choisir, double-clic pour choisir et rendre la quête. Ta touche Platyplus et Échap marchent comme avant. Coupé : les fenêtres du jeu reviennent."] = "Ejemplo: hablas con el guardia, sus opciones y sus misiones aparecen como líneas en las que se puede pulsar; eliges una misión y su texto, sus objetivos y sus recompensas se muestran en grande con los botones Aceptar / Rechazar. Las recompensas son casillas de color según su rareza: pasa el ratón para ver la descripción emergente, clic para elegir, doble clic para elegir y entregar la misión. Tu tecla de Platyplus y Esc funcionan como antes. Desactivado: vuelven las ventanas del juego.",
    ["Exemple : un mage dont un sort se met à briller sur sa barre voit son icône apparaître en grand avec la touche. Mage, démoniste, prêtre, druide et chaman passent surtout par là, comme les sorts de rune. Les sorts réactifs du guerrier peuvent aussi briller : coupe cette option si tu ne veux que la liste des sorts réactifs."] = "Ejemplo: si un hechizo de un mago empieza a brillar en su barra, su icono aparece en grande con la tecla. Mago, brujo, sacerdote, druida y chamán pasan sobre todo por aquí, igual que los hechizos rúnicos. Los hechizos reactivos del guerrero también pueden brillar: desactiva esta opción si solo quieres la lista de hechizos reactivos.",
    ["Exemple : un mage dont un sort se met à briller sur sa barre voit son icône apparaître en grand avec la touche. Mage, démoniste, prêtre, druide et chaman passent surtout par là, comme les sorts de rune. Pour un guerrier, Fulgurance et les autres brillent peut-être aussi (à confirmer en jeu) : coupe cette option si tu ne veux que la liste de sorts réactifs."] = "Ejemplo: a un mago, cuando un hechizo empieza a brillar en su barra, ve aparecer su icono en grande con la tecla. Mago, brujo, sacerdote, druida y chamán pasan sobre todo por aquí, igual que los hechizos rúnicos. Para un guerrero, Abrumar y los demás quizá también brillen (por confirmar en el juego): desactiva esta opción si solo quieres la lista de hechizos reactivos.",
    ["Exemple : un prêtre et un druide dans ton groupe, et tu n'as ni Robustesse ni Marque du fauve : deux icônes apparaissent au-dessus de ton personnage, avec « Ariane » et « Cléo » dessous. Proposés : Robustesse (prêtre), Marque du fauve (druide), Intelligence des arcanes (mage, si tu utilises de la mana), une bénédiction (paladin : puissance, ou sagesse si tu utilises de la mana ; n'importe laquelle compte). Cachée en combat."] = "Ejemplo: hay un sacerdote y un druida en tu grupo y no tienes ni Entereza ni Marca de lo Salvaje: aparecen dos iconos sobre tu personaje, con «Ariane» y «Cléo» debajo. Se proponen: Entereza (sacerdote), Marca de lo Salvaje (druida), Intelecto Arcano (mago, si usas maná), una bendición (paladín: poderío, o sabiduría si usas maná; cuenta cualquiera). Oculta en combate.",
    ["Exemple : « Fulgurance » écrit sous l'icône. Coupé, l'alerte est plus compacte."] = "Ejemplo: «Abrumar» escrito bajo el icono. Si lo desactivas, la alerta es más compacta.",
    ["Exemple avec le seuil à 20 % : ton healer a 6 800 de mana au maximum ; dès qu'il passe sous 1 360, la barre et son contour deviennent rouges et la barre clignote une fois. L'alerte se retire quand il remonte à 25 %, pour ne pas clignoter autour du seuil. Pendant les combats où le jeu cache la mana des alliés, la barre devient seulement rouge (sans clignotement ni son)."] = "Ejemplo con el umbral al 20 %: tu sanador tiene 6 800 de maná como máximo; en cuanto baja de 1 360, la barra y su contorno se ponen rojos y la barra parpadea una vez. La alerta se retira cuando sube al 25 %, para no parpadear alrededor del umbral. En los combates en que el juego oculta el maná de los aliados, la barra solo se pone roja (sin parpadeo ni sonido).",
    ["Expérience"] = "Experiencia",
    ["Expérience : le pourcentage du niveau. Clique dessus pour voir l'XP par heure, le temps avant le niveau ou les mobs restants."] = "Experiencia: el porcentaje del nivel. Haz clic para ver la XP por hora, el tiempo hasta el siguiente nivel o los monstruos restantes.",
