    ["Fine (jeu)"] = "Fina (juego)",
    ["Fluidité de l'affichage. Vert : 50 et plus, orange : 25 à 49, rouge : moins de 25."] = "Fluidez de la imagen. Verde: 50 o más, naranja: 25 a 49, rojo: menos de 25.",
    ["Fluidité du jeu (images par seconde)."] = "Fluidez del juego (fotogramas por segundo).",
    ["Flux Platyplus - glisse-moi"] = "Flujo de Platyplus - arrástrame",
    ["Flux de butin"] = "Flujo de botín",
    ["Flux de butin à l'écran"] = "Flujo de botín en pantalla",
