    ["Folie"] = "Locura",
    ["Fond uni sans les bords arrondis (sa couleur et sa transparence restent celles réglées dans le jeu), onglets plats avec un trait bleu sous celui qui est actif, zone de saisie sombre bordée de bleu. Coupé : le chat redevient exactement comme avant."] = "Fondo liso sin bordes redondeados (su color y su transparencia siguen siendo los configurados en el juego), pestañas planas con una línea azul bajo la activa, cuadro de texto oscuro con borde azul. Desactivado: el chat vuelve a ser exactamente como antes.",
    ["Fond uni, onglets plats, zone de saisie sombre."] = "Fondo liso, pestañas planas, cuadro de texto oscuro.",
    ["Fond, bord et coins arrondis comme réglés dans la carte « Cadre »."] = "Fondo, borde y esquinas redondeadas según lo configurado en la tarjeta «Marco».",
    ["Format"] = "Formato",
    ["Fragments d'âme"] = "Fragmentos de alma",
    ["Fulgurance, Vengeance, Exécution, Ivresse de la victoire"] = "Abrumar, Venganza, Ejecutar, Ímpetu de victoria",
    ["Fureur"] = "Furia",
    ["Gagné par %s"] = "Ganado por %s",
    ["Gagnée cette session"] = "Ganado en esta sesión",
    ["Garde l'étincelle de butin du jeu allumée."] = "Mantiene encendido el destello de botín del juego.",
    ["Garder les apparences que je n'ai pas"] = "Conservar las apariencias que no tengo",
    ["Garder les derniers messages"] = "Conservar los últimos mensajes",
    ["Gardé pour ce personnage"] = "Guardado para este personaje",
    ["Glisse ici un objet de tes sacs"] = "Arrastra aquí un objeto de tus bolsas",
    ["Glisse ici un sort de ton grimoire"] = "Arrastra aquí un hechizo de tu libro de hechizos",
    ["Gris"] = "Gris",
    ["Gris : %d"] = "Gris: %d",
    ["Groupe"] = "Grupo",
    ["Groupe (%d)"] = "Grupo (%d)",
    ["Groupes, duels et invocations"] = "Grupos, duelos e invocaciones",
    ["Groupes, duels et invocations acceptés ou refusés pour toi ; une interface plus calme."] = "Grupos, duelos e invocaciones aceptados o rechazados por ti; una interfaz más tranquila.",
    ["Guerrier"] = "Guerrero",
    ["Guerrier : Fulgurance, Vengeance, Exécution, Ivresse de la victoire. Voleur : Riposte. Chasseur : Contre-attaque, Morsure de la mangouste, Ordre de tuer. Paladin : Marteau de courroux. Exemple : tu pares un coup, Riposte apparaît avec sa touche. Coupé, ces sorts ne sont plus annoncés (sauf s'ils brillent et que « Sorts qui brillent » est actif)."] = "Guerrero: Abrumar, Venganza, Ejecutar, Ímpetu de victoria. Pícaro: Ripostar. Cazador: Contraataque, Mordedura de mangosta, Orden de matar. Paladín: Martillo de cólera. Ejemplo: paras un golpe y Ripostar aparece con su tecla. Si lo desactivas, estos hechizos dejan de anunciarse (salvo si brillan y «Hechizos que brillan» está activado).",
    ["Guerrier : une petite icône quand le buff est actif."] = "Guerrero: un pequeño icono cuando el beneficio está activo.",
    ["Guilde"] = "Hermandad",
    ["HDV"] = "Casa de subastas",
    ["HDV : %s ne sera plus proposé (/pp hdv exclus pour la liste)"] = "Casa de subastas: %s ya no se propondrá (/pp hdv exclus para ver la lista)",
    ["HDV : %s refusé"] = "Casa de subastas: %s rechazado",
    ["HDV : %s refusé (%s)"] = "Casa de subastas: %s rechazado (%s)",
    ["HDV : coche d'abord les objets à mettre en vente (clic sur la ligne)"] = "Casa de subastas: primero marca los objetos que quieres vender (clic en la línea)",
    ["HDV : le jeu demande une confirmation pour %s. Clique encore (ou ta touche) pour confirmer."] = "Casa de subastas: el juego pide confirmación para %s. Haz clic de nuevo (o tu tecla) para confirmar.",
    ["HDV : le scan complet n'a rien renvoyé."] = "Casa de subastas: el escaneo completo no devolvió nada.",
    ["HDV : le serveur n'autorise un scan complet que toutes les 15 min, réessaie dans %d min."] = "Casa de subastas: el servidor solo permite un escaneo completo cada 15 min, inténtalo de nuevo en %d min.",
    ["HDV : pas de réponse au scan complet, réessaie plus tard."] = "Casa de subastas: sin respuesta al escaneo completo, inténtalo más tarde.",
    ["HDV : prix trouvés."] = "Casa de subastas: precios encontrados.",
    ["HDV : recherche des prix en cours, patiente un instant"] = "Casa de subastas: buscando precios, espera un momento",
    ["HDV : rien de prêt à mettre en vente"] = "Casa de subastas: nada listo para poner a la venta",
    ["HDV : scan complet lancé (tous les prix de l'HDV, quelques secondes)..."] = "Casa de subastas: escaneo completo iniciado (todos los precios, unos segundos)...",
    ["HDV : scan complet refusé par le jeu"] = "Casa de subastas: escaneo completo rechazado por el juego",
    ["HDV : scan complet terminé, %d objet(s) avec un prix."] = "Casa de subastas: escaneo completo terminado, %d objeto(s) con precio.",
    ["Hauteur de la barre"] = "Altura de la barra",
    ["Healer suivi"] = "Sanador seguido",
    ["Histoire de la quête"] = "Historia de la misión",
    ["Hors combat"] = "Fuera de combate",
    ["Hors combat : boit la boisson la plus haute (eau, jus...) pour la mana. En combat : boit ta meilleure potion de mana. Remettre « aucune » coupe la touche."] = "Fuera de combate: bebe la mejor bebida (agua, zumo...) para el maná. En combate: bebe tu mejor poción de maná. Volver a poner «ninguna» desactiva la tecla.",
    ["Hors combat : l'icône du buff manquant avec le nom de l'allié."] = "Fuera de combate: el icono del beneficio que falta con el nombre del aliado.",
    ["Hors combat : l'icône du buff qui te manque et le nom de l'allié qui peut te le donner."] = "Fuera de combate: el icono del beneficio que te falta y el nombre del aliado que puede dártelo.",
    ["Hors combat : mange la nourriture la plus haute que tu peux utiliser. En combat : boit ta meilleure potion de soins. « La plus haute » = niveau requis, puis niveau de l'objet. Remettre « aucune » coupe la touche."] = "Fuera de combate: come la mejor comida que puedas usar. En combate: bebe tu mejor poción de curación. «La mejor» = nivel requerido y, después, nivel del objeto. Volver a poner «ninguna» desactiva la tecla.",
    ["Hors combat · quête · rare"] = "Fuera de combate — misión — raro",
    ["Hostile"] = "Hostil",
    ["Hôtel des ventes"] = "Casa de subastas",
    ["ID d'objet ou lien, puis Entrée"] = "ID de objeto o enlace y luego Intro",
    ["Icône & infos"] = "Icono e información",
    ["Icône Platyplus"] = "Icono de Platyplus",
    ["Icône de Maîtrise du blocage"] = "Icono de Maestría de bloqueo",
    ["Icônes"] = "Iconos",
    ["Il n'est pas sur ta liste de menace"] = "No está en tu lista de amenaza",
    ["Il ne t'attaque que si tu le tapes."] = "Solo te ataca si tú lo golpeas.",
    ["Il ne te tape pas"] = "No te está golpeando",
    ["Il t'a échappé"] = "Se te ha escapado",
    ["Il tape un allié"] = "Golpea a un aliado",
    ["Il te manque encore des objets ou des objectifs."] = "Aún te faltan objetos u objetivos.",
    ["Il te tape"] = "Te golpea",
    ["Images par seconde"] = "Fotogramas por segundo",
    ["Immersif"] = "Inmersivo",
    ["Immobilise"] = "Inmoviliza",
    ["Incantations"] = "Lanzamientos",
    ["Inclure les objets « lié quand équipé »"] = "Incluir los objetos «ligado al equiparlo»",
    ["Inhabituel"] = "Poco común",
    ["Interaction rapide"] = "Interacción rápida",
    ["Interagit avec ce que tu survoles, sinon avec la cible la plus proche."] = "Interactúa con lo que señalas con el ratón o, si no, con el objetivo más cercano.",
    ["Interface"] = "Interfaz",
    ["Interface et caméra"] = "Interfaz y cámara",
    ["Interruptible"] = "Interrumpible",
    ["Inutilisable"] = "Inutilizable",
    ["Jamais moins que le marchand"] = "Nunca menos que el vendedor",
    ["Je joue"] = "Yo juego",
    ["Jets /roll"] = "Tiradas /roll",
    ["Jets de butin"] = "Tiradas de botín",
    ["Jets de dés en groupe"] = "Tiradas de dados en grupo",
    ["Jets en cours"] = "Tiradas en curso",
    ["Jeu"] = "Juego",
    ["Joue un avertissement quand l'alerte se déclenche. Hors combat, pas de son : un healer qui boit est à sec exprès. Le bouton « Aperçu » le fait entendre."] = "Reproduce un aviso cuando salta la alerta. Fuera de combate no suena: un sanador que bebe se queda sin maná a propósito. El botón «Vista previa» lo hace sonar.",
    ["Jouer"] = "Jugar",
    ["Journal des donjons"] = "Diario de mazmorras",
    ["L'HDV garde 5 % de chaque vente. Exemple : minerai à 18 pc à l'HDV, il te reste 17 pc, contre 5 pc chez le marchand : il est mis en vente. À 5 pc à l'HDV, il ne te resterait que 4 pc : il est marqué « marchand mieux » et reste dans tes sacs."] = "La casa de subastas se queda el 5 % de cada venta. Ejemplo: mineral a 18 pc en la casa de subastas, te quedan 17 pc, frente a 5 pc con el vendedor: se pone a la venta. A 5 pc en la casa de subastas, solo te quedarían 4 pc: se marca como «mejor al vendedor» y se queda en tus bolsas.",
    ["L'addon DungeonJournal séparé est activé : c'est lui qui tourne, avec la liste des donjons, « À ton niveau » et le style de Platyplus posés dessus. Le journal intégré à Platyplus reste éteint et garde une copie de ses réglages, de tes favoris et de ta progression : désactive DungeonJournal dans la liste des addons (écran de choix du personnage) puis relance le jeu pour revenir au journal intégré."] = "El addon DungeonJournal por separado está activado: es el que funciona, con la lista de mazmorras, «A tu nivel» y el estilo de Platyplus puestos encima. El diario integrado en Platyplus sigue apagado y guarda una copia de sus ajustes, tus favoritos y tu progreso: desactiva DungeonJournal en la lista de addons (pantalla de selección de personaje) y reinicia el juego para volver al diario integrado.",
    ["L'alerte apparaît quand le sort est vraiment utilisable (bonne posture, assez de rage, pas en recharge) et disparaît dès qu'il ne l'est plus. La touche est celle du bouton où tu as rangé le sort : un sort absent de tes barres n'est pas annoncé. Choisis les sorts surveillés dans la carte du dessous. /pp proc liste tes sorts surveillés et leur touche."] = "La alerta aparece cuando el hechizo es realmente utilizable (actitud correcta, ira suficiente, sin reutilización) y desaparece en cuanto deja de serlo. La tecla es la del botón donde has colocado el hechizo: un hechizo que no esté en tus barras no se anuncia. Elige los hechizos vigilados en la tarjeta de abajo. /pp proc muestra tus hechizos vigilados y su tecla.",
    ["L'alerte quand une technique devient utilisable (Fulgurance, Riposte…) : quoi surveiller, comment l'afficher."] = "La alerta cuando una habilidad pasa a ser utilizable (Abrumar, Revancha…): qué vigilar y cómo mostrarlo.",
    ["L'alerte se déclenche quand il te reste ce nombre d'emplacements libres, ou moins."] = "La alerta salta cuando te queda este número de huecos libres, o menos.",
    ["L'argent de ce personnage."] = "El dinero de este personaje.",
    ["L'aspect de la barre colorée. Unie = couleur plate, sans reflet."] = "El aspecto de la barra de color. Lisa = color plano, sin brillo.",
    ["L'heure devant chaque message"] = "La hora delante de cada mensaje",
    ["L'icône Platyplus"] = "El icono de Platyplus",
    ["L'icône Platyplus et sa barre d'infos, où tu veux à l'écran."] = "El icono de Platyplus y su barra de información, donde quieras en la pantalla.",
    ["L'icône du sort qui vient de devenir utilisable, sous ton personnage, avec la touche à presser."] = "El icono del hechizo que acaba de ser utilizable, bajo tu personaje, con la tecla que pulsar.",
    ["L'étincelle du jeu oublie certains cadavres, les boss notamment. Une fois le combat fini, un cadavre qui a encore du butin pour toi brille quand tu t'en approches. Elle dit seulement « il reste du butin », pas quoi. Le jeu pose alors sa plaque de nom (nom et barre de vie) sur ce cadavre : c'est elle qui porte l'étincelle. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "El destello del juego olvida algunos cadáveres, sobre todo los jefes. Terminado el combate, un cadáver que aún tiene botín para ti brilla cuando te acercas. Solo dice «queda botín», no cuál. El juego coloca entonces su placa de nombre (nombre y barra de vida) sobre ese cadáver: ella lleva el destello. Usa la selección de interacción del juego: el objeto más cercano, hasta unos 15 m a tu alrededor. Para ello Platyplus activa «Activar la tecla de interacción» y los iconos de interacción de los objetos del mundo del juego, y los deja como estaban cuando desactivas todos los destellos de abajo. Sin destellos durante un combate.",
    ["La barre de sort sous la plate d'un mob qui incante."] = "La barra de lanzamiento bajo la placa de nombre de un monstruo que está lanzando un hechizo.",
    ["La fenêtre de réglages du journal lui-même : bouton de la minicarte, infobulles des objets, quêtes de classe et de métier, mode RPG... (aussi : /dj options)."] = "La ventana de ajustes del propio diario: botón del minimapa, descripciones emergentes de los objetos, misiones de clase y de profesión, modo RPG... (también: /dj options).",
    ["La langue du message envoyé (le menu reste en français). En anglais, avec les abréviations des joueurs : « Hi, could I get BoK pls? Thanks :) » (Fort, MotW, Int…) ; « Tous ses buffs » : « Hi, could I get buff pls? Thanks :) »."] = "El idioma del mensaje enviado (el menú no cambia). En inglés, con las abreviaturas de los jugadores: «Hi, could I get BoK pls? Thanks :)» (Fort, MotW, Int…); «Todos sus beneficios»: «Hi, could I get buff pls? Thanks :)».",
    ["La menace d'un coup d'œil"] = "La amenaza de un vistazo",
    ["La repérer au milieu d'un pack."] = "Para localizarla en medio de un grupo de monstruos.",
    ["La touche"] = "La tecla",
    ["La touche choisie interagit d'abord avec ce que la souris survole, sinon avec la cible d'interaction la plus proche : PNJ, coffre, plante, cadavre à dépouiller. Coupée, Platyplus ne lie plus aucune touche."] = "La tecla elegida interactúa primero con lo que señala el ratón o, si no, con el objetivo de interacción más cercano: PNJ, cofre, planta, cadáver que despellejar. Desactivada, Platyplus ya no asigna ninguna tecla.",
    ["La touche à presser, en gros sous l'icône (« 3 », « Maj+E »)."] = "La tecla que pulsar, en grande bajo el icono («3», «Mayús+E»).",
    ["Laisser le jeu choisir"] = "Dejar que el juego elija",
    ["Lancer les sorts à l'appui de la touche"] = "Lanzar los hechizos al pulsar la tecla",
    ["Langue"] = "Idioma",
    ["Langue changée. Les textes déjà affichés ailleurs (barre d'infos, options du jeu) suivront au prochain /reload."] = "Idioma cambiado. Los textos ya mostrados en otros sitios (barra de información, opciones del juego) cambiarán en el próximo /reload.",
    ["Langue de Platyplus"] = "Idioma de Platyplus",
    ["Langue de la demande"] = "Idioma de la petición",
    ["Langue des textes de Platyplus. Les textes pas encore traduits restent en anglais, ou en français à défaut."] = "Idioma de los textos de Platyplus. Los textos aún sin traducir se quedan en inglés o, en su defecto, en francés.",
    ["Largeur"] = "Anchura",
    ["Largeur de la barre de coups blancs."] = "Anchura de la barra de golpes automáticos.",
    ["Largeur de la barre, en points d'interface."] = "Anchura de la barra, en puntos de interfaz.",
    ["Latence"] = "Latencia",
    ["Le bord de la plate de ta cible est plus épais et de la couleur choisie."] = "El borde de la placa de nombre de tu objetivo es más grueso y del color elegido.",
    ["Le butin sans clics"] = "El botín sin clics",
    ["Le choix est gardé tout de suite, mais les fenêtres déjà construites gardent l'ancienne langue : recharge l'interface (bouton ci-dessous ou /reload)."] = "La elección se guarda al instante, pero las ventanas ya creadas conservan el idioma anterior: recarga la interfaz (botón de abajo o /reload).",
    ["Le clignotement fait toujours trois éclats, plus ou moins vite."] = "El parpadeo siempre da tres destellos, más o menos rápido.",
    ["Le confort tout-en-un"] = "La comodidad todo en uno",
    ["Le confort tout-en-un pour WoW Forever · v%s"] = "La comodidad todo en uno para WoW Forever · v%s",
    ["Le confort tout-en-un · v%s"] = "La comodidad todo en uno · v%s",
    ["Le contour et le fond autour de la barre."] = "El contorno y el fondo alrededor de la barra.",
    ["Le fond visible là où le mob a perdu de la vie. 0 % = transparent."] = "El fondo visible donde el monstruo ha perdido vida. 0 % = transparente.",
    ["Le gros cadre sombre du jeu remplacé par le nôtre, réglable ci-dessous."] = "El gran marco oscuro del juego sustituido por el nuestro, configurable abajo.",
    ["Le healer est celui que le groupe désigne comme soigneur (file de donjon, ou rôle donné par le chef de groupe). Si personne n'a ce rôle, cible ton healer et clique « Mon healer = ma cible ». S'il y a plusieurs soigneurs, la barre suit le premier de la liste du groupe : choisis le tien avec le bouton."] = "El sanador es el que el grupo designa como tal (buscador de mazmorras o rol dado por el líder del grupo). Si nadie tiene ese rol, selecciona a tu sanador y pulsa «Mi sanador = mi objetivo». Si hay varios sanadores, la barra sigue al primero de la lista del grupo: elige el tuyo con el botón.",
    ["Le jeu fait briller les objets de quête à ramasser (une caisse, une torche par terre...), mais un préréglage graphique coupe cette étincelle. Platyplus la remet à la connexion et juste après chaque changement graphique. Ton mode de contour (outline) n'est pas touché. Couper cette option ne prend effet qu'après un redémarrage du jeu : /reload ne suffit pas."] = "El juego hace brillar los objetos de misión que recoger (una caja, una antorcha en el suelo...), pero un preajuste gráfico desactiva ese destello. Platyplus lo reactiva al conectarse y justo después de cada cambio gráfico. Tu modo de contorno (outline) no se toca. Desactivar esta opción solo surte efecto tras reiniciar el juego: /reload no basta.",
    ["Le jeu marque déjà la plupart des objets de quête avec son étincelle de butin. Ceci en ajoute une autre sur ceux que ton journal demande encore, d'après le nom de l'objectif (« Caisse de provisions »...). Coupé par défaut. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "El juego ya marca la mayoría de los objetos de misión con su destello de botín. Esto añade otro en los que tu diario aún pide, según el nombre del objetivo («Caja de provisiones»...). Desactivado por defecto. Usa la selección de interacción del juego: el objeto más cercano, hasta unos 15 m a tu alrededor. Para ello Platyplus activa «Activar la tecla de interacción» y los iconos de interacción de los objetos del mundo del juego, y los deja como estaban cuando desactivas todos los destellos de abajo. Sin destellos durante un combate.",
    ["Le jeu protège une partie des caractéristiques en ce moment : affichage simplifié, sans détail au survol. Tout revient dès qu'il les rend lisibles."] = "El juego protege parte de las características en este momento: visualización simplificada, sin detalle al pasar el ratón. Todo vuelve en cuanto las hace legibles.",
    ["Le joueur dont la barre montre la mana. « Aucun » : ton groupe n'a pas de soigneur désigné et tu n'as pas choisi ton healer à la main."] = "El jugador cuya maná muestra la barra. «Ninguno»: tu grupo no tiene un sanador designado y no has elegido a tu sanador a mano.",
    ["Le journal aux couleurs de Platyplus : fond sombre arrondi, liserés fins, sélection en bleu, texte clair, et plus de parchemin sous les quêtes. Rien ne bouge : mêmes pages, mêmes boutons. Éteint : le look d'origine du journal (pierre, bronze et or). Prend effet après /reload."] = "El diario con los colores de Platyplus: fondo oscuro redondeado, ribetes finos, selección en azul, texto claro y sin pergamino bajo las misiones. Nada cambia de sitio: mismas páginas, mismos botones. Desactivado: el aspecto original del diario (piedra, bronce y oro). Surte efecto tras /reload.",
    ["Le journal de quêtes de la carte du monde du jeu."] = "El diario de misiones del mapa del mundo del juego.",
    ["Le journal des donjons : boss, butin, quêtes et plans de chaque donjon."] = "El diario de mazmorras: jefes, botín, misiones y mapas de cada mazmorra.",
    ["Le journal des donjons est celui de l'addon DungeonJournal d'Exehn, installé à part : Platyplus l'ouvre d'ici, depuis le menu de l'icône et avec /pp donjons."] = "El diario de mazmorras es el del addon DungeonJournal de Exehn, instalado por separado: Platyplus lo abre desde aquí, desde el menú del icono y con /pp donjons.",
    ["Le journal des donjons est celui de l'addon DungeonJournal d'Exehn, installé à part. Platyplus l'ouvre d'ici, depuis le menu de l'icône et avec /pp donjons, et pose dessus sa liste des donjons, « À ton niveau » et son style, sans rien changer dans l'addon."] = "El diario de mazmorras es el del addon DungeonJournal de Exehn, instalado por separado. Platyplus lo abre desde aquí, desde el menú del icono y con /pp donjons, y le pone encima su lista de mazmorras, «A tu nivel» y su estilo, sin cambiar nada en el addon.",
    ["Le journal des donjons n'est pas inclus dans cette version de Platyplus. Installe l'addon DungeonJournal d'Exehn depuis CurseForge : Platyplus l'ouvrira ensuite depuis cet onglet, depuis le menu de l'icône et avec /pp donjons, et posera dessus sa liste des donjons, « À ton niveau » et son style."] = "El diario de mazmorras no está incluido en esta versión de Platyplus. Instala el addon DungeonJournal de Exehn desde CurseForge: Platyplus lo abrirá después desde esta pestaña, desde el menú del icono y con /pp donjons, y le pondrá encima su lista de mazmorras, «A tu nivel» y su estilo.",
    ["Le journal des donjons n'est pas inclus dans cette version de Platyplus. Installe l'addon DungeonJournal d'Exehn depuis CurseForge : Platyplus l'ouvrira ensuite depuis cet onglet, depuis le menu de l'icône et avec /pp donjons."] = "El diario de mazmorras no está incluido en esta versión de Platyplus. Instala el addon DungeonJournal de Exehn desde CurseForge: Platyplus lo abrirá después desde esta pestaña, desde el menú del icono y con /pp donjons.",
    ["Le marchand t'en donne"] = "El vendedor te da",
    ["Le minuteur de ton attaque automatique : la barre se remplit jusqu'au prochain coup blanc. Pratique pour placer Frappe héroïque ou Heurtoir au bon moment."] = "El temporizador de tu ataque automático: la barra se llena hasta el siguiente golpe automático. Práctico para colocar Golpe heroico o Azote en el momento justo.",
    ["Le mode Recommandé, plus : les groupes de tes amis et de ta guilde acceptés, les invocations et les résurrections acceptées, les duels refusés, tout le courrier ouvert d'un coup, les quêtes acceptées et rendues sans appuyer sur la touche, la barre de mana du healer, la caméra plus loin, les têtes parlantes masquées, les objets de quête qui brillent."] = "El modo Recomendado, y además: grupos de tus amigos y de tu hermandad aceptados, invocaciones y resurrecciones aceptadas, duelos rechazados, todo el correo abierto de una vez, misiones aceptadas y entregadas sin pulsar la tecla, la barra de maná del sanador, la cámara más lejos, las cabezas parlantes ocultas, los objetos de misión que brillan.",
    ["Le nom du sort, en petit sous la touche."] = "El nombre del hechizo, en pequeño bajo la tecla.",
    ["Le petit logo en haut à droite de la fenêtre de chat."] = "El pequeño logotipo arriba a la derecha de la ventana de chat.",
    ["Le prix de tes objets à l'hôtel des ventes, partout : dans les infobulles et avant de fabriquer. Les prix viennent d'un scan complet de l'HDV et de ce que l'assistant trouve."] = "El precio de tus objetos en la casa de subastas, en todas partes: en las descripciones emergentes y antes de fabricar. Los precios proceden de un escaneo completo de la casa de subastas y de lo que encuentra el asistente.",
    ["Le son d'avertissement de raid, au plus une fois par seconde."] = "El sonido de aviso de banda, como máximo una vez por segundo.",
    ["Le sort part quand tu appuies, pas quand tu relâches. Disponible seulement si le client connaît ce réglage."] = "El hechizo se lanza al pulsar, no al soltar. Solo disponible si el cliente reconoce este ajuste.",
    ["Les 100 dernières lignes de chaque fenêtre, pour la session suivante."] = "Las últimas 100 líneas de cada ventana, para la sesión siguiente.",
    ["Les adresses web écrites dans le chat (https://..., www....) deviennent des liens bleus. Un clic ouvre une petite fenêtre avec le lien déjà sélectionné : Ctrl+C pour le copier. Les messages protégés par le jeu (instances, combats de boss) ne sont jamais touchés."] = "Las direcciones web escritas en el chat (https://..., www....) se convierten en enlaces azules. Un clic abre una ventanita con el enlace ya seleccionado: Ctrl+C para copiarlo. Los mensajes protegidos por el juego (instancias, combates de jefe) nunca se tocan.",
    ["Les armes et armures de qualité inférieure ne sont pas proposées. Par défaut Inhabituel (vert) : l'équipement blanc ou gris ne se vend pas à l'HDV, il part chez le marchand. Les marchandises (minerais, herbes, tissus...) sont toujours proposées."] = "Las armas y armaduras de calidad inferior no se proponen. Por defecto Poco común (verde): el equipo blanco o gris no se vende en la casa de subastas, va al vendedor. Las mercancías (minerales, hierbas, telas...) siempre se proponen.",
    ["Les barres de vie au-dessus des mobs : couleurs de menace, quêtes, rares, et tout leur look."] = "Las barras de vida sobre los monstruos: colores de amenaza, misiones, raros y todo su aspecto.",
    ["Les barres de vie des mobs changent de couleur selon qui ils attaquent. Ton rôle (tank ou dégâts) est deviné tout seul."] = "Las barras de vida de los monstruos cambian de color según a quién atacan. Tu rol (tanque o daño) se detecta solo.",
    ["Les dés lancés à la main dans le chat, rangés par objet annoncé."] = "Los dados tirados a mano en el chat, ordenados por objeto anunciado.",
    ["Les dés lancés à la main, rangés du plus haut au plus bas, avec l'objet lié juste avant dans le chat."] = "Las tiradas hechas a mano, ordenadas de mayor a menor, con el objeto enlazado justo antes en el chat.",
    ["Les fenêtres de chat du jeu (quand la fenêtre Platyplus est coupée) et la zone de saisie, aux couleurs de Platyplus."] = "Las ventanas de chat del juego (cuando la ventana de Platyplus está desactivada) y el cuadro de texto, con los colores de Platyplus.",
    ["Les fenêtres du jeu redessinées : plus grandes et plus lisibles."] = "Las ventanas del juego rediseñadas: más grandes y más legibles.",
    ["Les fonctions utiles sont allumées : la touche d'interaction, le loot instantané, la vente et la réparation, les alertes de combat, les plates de menace, les fenêtres Platyplus, le chat amélioré. Ce qui décide à ta place reste coupé : invitations, invocations, duels, courrier."] = "Las funciones útiles están activadas: la tecla de interacción, el botín instantáneo, la venta y la reparación, las alertas de combate, las placas de amenaza, las ventanas de Platyplus, el chat mejorado. Lo que decide por ti sigue desactivado: invitaciones, invocaciones, duelos, correo.",
    ["Les fonctions utiles sont déjà allumées : tu peux fermer cette fenêtre et jouer tout de suite."] = "Las funciones útiles ya están activadas: puedes cerrar esta ventana y jugar ya mismo.",
    ["Les fonctions utiles, sans rien décider à ta place. Le réglage de départ."] = "Las funciones útiles, sin decidir nada por ti. El ajuste inicial.",
    ["Les messages arrivent comme d'habitude (tes réglages de canaux du jeu restent valables) et s'affichent dans la fenêtre Platyplus, une bulle par message, le nom dans la couleur de sa classe, le texte en clair. L'onglet Chat montre ce que les joueurs disent, l'onglet Jeu le reste (butin, expérience, système). Tire le bandeau pour la déplacer, le coin en bas à droite pour la redimensionner. Clic sur l'heure d'un message : le copier. La zone de saisie reste celle du jeu (Entrée pour écrire). Coupé : les fenêtres de chat du jeu reviennent."] = "Los mensajes llegan como siempre (tus ajustes de canales del juego siguen valiendo) y se muestran en la ventana de Platyplus, un globo por mensaje, el nombre con el color de su clase y el texto en claro. La pestaña Chat muestra lo que dicen los jugadores y la pestaña Juego el resto (botín, experiencia, sistema). Arrastra la barra de título para moverla y la esquina de abajo a la derecha para cambiar su tamaño. Clic en la hora de un mensaje: copiarlo. El cuadro de texto sigue siendo el del juego (Intro para escribir). Desactivado: vuelven las ventanas de chat del juego.",
    ["Les miennes"] = "Las mías",
    ["Les miennes : hostile, neutre, amical et « tapé par d'autres » aux couleurs ci-dessous, avec ta texture. Celles du jeu : la barre normale du jeu. Les joueurs gardent toujours les couleurs du jeu."] = "Las mías: hostil, neutral, amistoso y «golpeado por otros» con los colores de abajo y tu textura. Las del juego: la barra normal del juego. Los jugadores siempre conservan los colores del juego.",
    ["Les mobs qui ne se battent pas avec toi."] = "Los monstruos que no combaten contigo.",
    ["Les objets au choix s'affichent au milieu de l'écran, colorés selon leur rareté."] = "Los objetos a elegir aparecen en medio de la pantalla, coloreados según su rareza.",
    ["Les objets exclus d'un clic droit dans le panneau de l'HDV seront de nouveau proposés."] = "Los objetos excluidos con clic derecho en el panel de la casa de subastas volverán a proponerse.",
    ["Les objets gris et l'équipement moins bon que le tien se vendent tout seuls. Tu peux les racheter chez le marchand."] = "Los objetos grises y el equipo peor que el tuyo se venden solos. Puedes recomprarlos al vendedor.",
    ["Les objets tirés au sort par le jeu (Besoin, Cupidité, Passer), boss par boss."] = "Los objetos sorteados por el juego (Necesidad, Codicia, Pasar), jefe por jefe.",
    ["Les pièces nettement moins bonnes que ce que tu portes."] = "Las piezas claramente peores que lo que llevas puesto.",
    ["Les plantes et les cadavres qui ont encore du butin pour toi scintillent quand tu approches."] = "Las plantas y los cadáveres que aún tienen botín para ti brillan cuando te acercas.",
    ["Les plus dangereux d'abord"] = "Los más peligrosos primero",
    ["Les sorts réactifs que Platyplus connaît pour ta classe. Pour en ajouter un autre, utilise la liste « Sorts ajoutés » juste en dessous."] = "Los hechizos reactivos que Platyplus conoce para tu clase. Para añadir otro, usa la lista «Hechizos añadidos» justo debajo.",
    ["Les tranches de niveau sont colorées selon ton niveau :\n|cff66e680vert|r à ton niveau, |cffffd133or|r bientôt (1 à 3 niveaux), |cffff6666rouge|r trop dur pour l'instant, |cff99a1b3gris|r dépassé.\nÀ droite : tes quêtes faites dans le donjon (✓ : toutes)."] = "Los tramos de nivel se colorean según tu nivel:\n|cff66e680verde|r a tu nivel, |cffffd133oro|r pronto (1 a 3 niveles), |cffff6666rojo|r demasiado difícil por ahora, |cff99a1b3gris|r superado.\nA la derecha: tus misiones hechas en la mazmorra (✓: todas).",
    ["Les étincelles (onglet Butin) règlent cette portée : coupe-les pour la changer ici."] = "Los destellos (pestaña Botín) fijan este alcance: desactívalos para cambiarlo aquí.",
    ["Lien [FR] pour traduire"] = "Enlace [FR] para traducir",
    ["Lien web"] = "Enlace web",
    ["Liens web cliquables"] = "Enlaces web pulsables",
    ["Lignes au maximum"] = "Máximo de líneas",
    ["Limite le nombre de pièces d'équipement vendues à chaque visite. Le rachat de Blizzard ne garde que les 12 derniers objets vendus : au-delà de 12, tu ne pourrais plus tout racheter en cas d'erreur."] = "Limita el número de piezas de equipo vendidas en cada visita. La recompra de Blizzard solo conserva los 12 últimos objetos vendidos: por encima de 12, no podrías recomprarlo todo en caso de error.",
    ["Lisibilité"] = "Legibilidad",
    ["Liste des donjons à gauche"] = "Lista de mazmorras a la izquierda",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Lista los monstruos en combate (placas de nombre, jefes, objetivos de tu grupo). Los colores son los de las placas de nombre (pestaña Placas). En mazmorra, el juego oculta ciertos valores a los addons: el color sigue siendo correcto, pero la ordenación por vida y algunas cifras pueden faltar. No se puede hacer clic para fijar objetivo: el juego lo prohíbe en combate.",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Survole une ligne : infobulle (état en clair, vie, menace) et la plate du mob est mise en évidence dans le monde ; clic droit : pose ou retire le marqueur Crâne. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Lista los enemigos en combate (placas, jefes, objetivos de tu grupo). Los colores son los de las placas (pestaña Placas). En mazmorras el juego oculta algunos valores a los addons: el color sigue siendo correcto, pero el orden por vida y algunas cifras pueden faltar. Pasa el ratón por una fila: descripción emergente (estado en claro, vida, amenaza) y la placa del enemigo se resalta en el mundo; clic derecho: pone o quita la marca de Calavera. Sin clic para seleccionar: el juego lo prohíbe en combate.",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Survole une ligne : infobulle (état en clair, vie, menace) et la plate du mob est mise en évidence dans le monde. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Lista los enemigos en combate (placas, jefes, objetivos de tu grupo). Los colores son los de las placas (pestaña Placas). En mazmorras el juego oculta algunos valores a los addons: el color sigue siendo correcto, pero el orden por vida y algunas cifras pueden faltar. Pasa el ratón por una fila: descripción emergente (estado en claro, vida, amenaza) y la placa del enemigo se resalta en el mundo. Sin clic para seleccionar: el juego lo prohíbe en combate.",
    ["Liste les objets de tes sacs que l'HDV accepte, avec un prix pour chacun. Ne sont jamais proposés : objets liés, équipement blanc ou gris, outils de métier (pioche, couteau à dépecer, canne à pêche...), objets d'un ensemble d'équipement. Clic sur une ligne : cocher / décocher. Seuls les objets cochés sont mis en vente. Clic droit : ne plus jamais proposer cet objet."] = "Lista los objetos de tus bolsas que acepta la casa de subastas, con un precio para cada uno. Nunca se proponen: objetos ligados, equipo blanco o gris, herramientas de profesión (pico, cuchillo de desollar, caña de pescar...), objetos de un conjunto de equipo. Clic en una línea: marcar / desmarcar. Solo se ponen a la venta los objetos marcados. Clic derecho: no volver a proponer nunca ese objeto.",
    ["Lit l'historique de butin du jeu : rien n'est envoyé aux autres joueurs."] = "Lee el historial de botín del juego: no se envía nada a los demás jugadores.",
